// Run with: node scripts/embed-fonts.cjs
const fs = require('fs');
const path = require('path');

const fontsDir = path.join(__dirname, '..', 'src', 'assets', 'fonts');
const outFile = path.join(fontsDir, 'arabicFonts.ts');

const reg = fs.readFileSync(path.join(fontsDir, 'NotoSansArabic-Regular.ttf'));
const bold = fs.readFileSync(path.join(fontsDir, 'NotoSansArabic-Bold.ttf'));

const regB64 = reg.toString('base64');
const boldB64 = bold.toString('base64');

const out = [
  '// Auto-generated by scripts/embed-fonts.cjs — do not edit manually.',
  '// Arabic fonts embedded as base64 for Vercel serverless compatibility.',
  'export const NOTO_ARABIC_REGULAR_B64 =',
  '  ' + JSON.stringify(regB64) + ';',
  'export const NOTO_ARABIC_BOLD_B64 =',
  '  ' + JSON.stringify(boldB64) + ';',
  '',
].join('\n');

fs.writeFileSync(outFile, out, 'utf8');
console.log('Written:', outFile, '| size:', out.length, 'chars');
